def max_window_sum(xs, k):
    if k <= 0 or k > len(xs):
        return None
    total = sum(xs[:k])
    best = total
    for i in range(1, len(xs) - k + 1):
        total = total - xs[i - 1] + xs[i + k - 1]
        if total > best:
            best = total
    return best
